CREATE TABLE IF NOT EXISTS results."airport_only_2025" ("airport_group" TEXT, "trips" BIGINT, "distance_n" BIGINT, "median_duration_min" DOUBLE PRECISION, "p90_duration_min" DOUBLE PRECISION, "median_distance_mi" DOUBLE PRECISION, "distance_sum_mi" DOUBLE PRECISION, "fare_n" BIGINT, "fare_sum_usd" DOUBLE PRECISION, "charge_sum_usd" DOUBLE PRECISION, "median_fare_usd" DOUBLE PRECISION, "median_charge_usd" DOUBLE PRECISION, "jfk_rate_records" BIGINT, "newark_rate_records" BIGINT);
CREATE TABLE IF NOT EXISTS results."annual_2025" ("report_year" BIGINT, "trips" BIGINT, "distance_n" BIGINT, "median_duration_min" DOUBLE PRECISION, "p90_duration_min" DOUBLE PRECISION, "median_distance_mi" DOUBLE PRECISION, "distance_sum_mi" DOUBLE PRECISION, "fare_n" BIGINT, "fare_sum_usd" DOUBLE PRECISION, "charge_sum_usd" DOUBLE PRECISION, "median_fare_usd" DOUBLE PRECISION, "median_charge_usd" DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS results."borough_2025" ("borough" TEXT, "trips" BIGINT, "pickup_share" DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS results."cleaning_funnel" ("stage_no" BIGINT, "stage" TEXT, "records" BIGINT, "removed_to_next" BIGINT);
