CREATE TABLE IF NOT EXISTS results."fare_hour_2025" ("hour" BIGINT, "trips" BIGINT, "distance_n" BIGINT, "median_duration_min" DOUBLE PRECISION, "p90_duration_min" DOUBLE PRECISION, "median_distance_mi" DOUBLE PRECISION, "distance_sum_mi" DOUBLE PRECISION, "fare_n" BIGINT, "fare_sum_usd" DOUBLE PRECISION, "charge_sum_usd" DOUBLE PRECISION, "median_fare_usd" DOUBLE PRECISION, "median_charge_usd" DOUBLE PRECISION);
