CREATE TABLE IF NOT EXISTS results."historical_year" ("year" BIGINT, "months_available" BIGINT, "raw_records" BIGINT, "compressed_bytes" BIGINT, "period_status" TEXT);
CREATE TABLE IF NOT EXISTS results."hour_2025" ("hour" BIGINT, "trips" BIGINT);
CREATE TABLE IF NOT EXISTS results."hourly_dashboard_2025" ("hour" BIGINT, "trips" BIGINT, "distance_n" BIGINT, "median_duration_min" DOUBLE PRECISION, "p90_duration_min" DOUBLE PRECISION, "median_distance_mi" DOUBLE PRECISION, "distance_sum_mi" DOUBLE PRECISION, "fare_n" BIGINT, "fare_sum_usd" DOUBLE PRECISION, "charge_sum_usd" DOUBLE PRECISION, "median_fare_usd" DOUBLE PRECISION, "median_charge_usd" DOUBLE PRECISION, "avg_daily_trips" DOUBLE PRECISION, "avg_daily_fare_usd" DOUBLE PRECISION, "avg_daily_charge_usd" DOUBLE PRECISION, "mean_fare_usd" DOUBLE PRECISION, "mean_charge_usd" DOUBLE PRECISION, "mean_distance_mi" DOUBLE PRECISION, "trip_share" DOUBLE PRECISION, "peak_status" TEXT, "hour_label" TEXT);
