CREATE TABLE IF NOT EXISTS results."negative_money_patterns" ("source_month" TEXT, "payment_type" BIGINT, "operational_valid" TEXT, "records" BIGINT, "both_negative" BIGINT, "fare_only_negative" BIGINT, "charge_only_negative" BIGINT, "nonpositive_duration" BIGINT, "zero_distance" BIGINT, "median_recorded_fare_usd" DOUBLE PRECISION);
