CREATE TABLE IF NOT EXISTS results."payment_diagnostics" ("payment_type" BIGINT, "payment_label" TEXT, "raw_records" BIGINT, "operational_trips" BIGINT, "fare_n" BIGINT, "negative_money_raw" BIGINT, "negative_money_operational" BIGINT, "missing_money" BIGINT, "zero_money" BIGINT, "median_eligible_fare_usd" DOUBLE PRECISION, "eligible_fare_sum_usd" DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS results."quality_long" ("metric" TEXT, "records" BIGINT);
CREATE TABLE IF NOT EXISTS results."quality_month" ("source_month" TEXT, "raw_records" BIGINT, "operational_trips" BIGINT, "pickup_outside_source_month" BIGINT, "missing_timestamps" BIGINT, "nonpositive_duration" BIGINT, "over_180_minutes" BIGINT, "zero_distance" BIGINT, "missing_distance" BIGINT, "implausible_distance" BIGINT, "negative_money" BIGINT, "disputed" BIGINT, "voided" BIGINT, "unknown_pickup" BIGINT, "unknown_dropoff" BIGINT, "fare_sample" BIGINT, "distance_sample" BIGINT);
CREATE TABLE IF NOT EXISTS results."rate_2025" ("rate_code" BIGINT, "trips" BIGINT, "distance_n" BIGINT, "median_duration_min" DOUBLE PRECISION, "p90_duration_min" DOUBLE PRECISION, "median_distance_mi" DOUBLE PRECISION, "distance_sum_mi" DOUBLE PRECISION, "fare_n" BIGINT, "fare_sum_usd" DOUBLE PRECISION, "charge_sum_usd" DOUBLE PRECISION, "median_fare_usd" DOUBLE PRECISION, "median_charge_usd" DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS results."route_top20_2025" ("pu" BIGINT, "do_zone" BIGINT, "pickup_zone" TEXT, "dropoff_zone" TEXT, "route" TEXT, "trips" BIGINT, "distance_n" BIGINT, "median_duration_min" DOUBLE PRECISION, "p90_duration_min" DOUBLE PRECISION, "median_distance_mi" DOUBLE PRECISION, "distance_sum_mi" DOUBLE PRECISION, "fare_n" BIGINT, "fare_sum_usd" DOUBLE PRECISION, "charge_sum_usd" DOUBLE PRECISION, "median_fare_usd" DOUBLE PRECISION, "median_charge_usd" DOUBLE PRECISION);
