CREATE TABLE IF NOT EXISTS results."sensitivity_2025" ("raw_records" BIGINT, "positive_duration_in_month" BIGINT, "within_120min" BIGINT, "within_180min" BIGINT, "within_240min" BIGINT, "positive_distance_operations" BIGINT);
