CREATE TABLE IF NOT EXISTS results."zone_balance_top20" ("location_id" BIGINT, "zone" TEXT, "borough" TEXT, "pickups" BIGINT, "dropoffs" BIGINT, "net_dropoffs" BIGINT, "direction" TEXT);
