CREATE TABLE IF NOT EXISTS results."zone_pickup_dropoff_2025" ("location_id" BIGINT, "zone" TEXT, "borough" TEXT, "pickups" BIGINT, "dropoffs" BIGINT, "net_dropoffs" BIGINT, "direction" TEXT);
CREATE TABLE IF NOT EXISTS results."zone_top15_2025" ("location_id" BIGINT, "zone" TEXT, "borough" TEXT, "trips" BIGINT, "pickup_share" DOUBLE PRECISION, "median_duration_min" DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS taxi_analysis.raw_trip_source (
source_month text,tpep_pickup_datetime timestamp,tpep_dropoff_datetime timestamp,trip_distance double precision,
pulocationid bigint,dolocationid bigint,ratecodeid double precision,payment_type bigint,fare_amount double precision,
total_amount double precision,tip_amount double precision,cbd_congestion_fee double precision);
CREATE TABLE IF NOT EXISTS taxi_analysis.zones (locationid bigint PRIMARY KEY,borough text,zone text,service_zone text);
CREATE OR REPLACE VIEW taxi_analysis.historical_month AS SELECT * FROM results.historical_month;
CREATE TABLE IF NOT EXISTS evidence.taxi_knowledge (id integer PRIMARY KEY,payload text NOT NULL,sha256 char(64) NOT NULL);
CREATE TABLE IF NOT EXISTS evidence.taxi_sources (path text PRIMARY KEY,sha256 char(64) NOT NULL,content bytea NOT NULL);
CREATE TABLE IF NOT EXISTS evidence.taxi_chunks (chunk_id text PRIMARY KEY,source_path text NOT NULL,payload jsonb NOT NULL);
